  for (int i = 1; i <= 8; i++) {
    float t = float(i) / 8.0, v = 1.0 - t;
    vec2 next = v*v*v*a.xy + 3.0*v*v*t*a.zw + 3.0*v*t*t*b.xy + t*t*t*b.zw;
    vec2 edge = next - previous;
    float u = clamp(dot(p - previous, edge) / max(.0001, dot(edge, edge)), 0.0, 1.0);
    float along = (float(i - 1) + u) / 8.0;
    float width = mix(jointMeta.y, jointMeta.z, smoothstep(0.0, 1.0, along));
