  vec2 outward = vec2(l - r, t - b);
  float lighting = 1.0 + dot(outward, vec2(-.65, -.76)) * .18 * length(sourceNormal.xy);
  vec3 rgb = styleColor.rgb * surface * lighting;
  return vec4(rgb * color.rgb, a * color.a * styleColor.a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

